formData.jsFunction:
def validate(request, response = [:]) {

    if (!request.containsKey("executionType")) {
        response.executionType = "The required executionType in the formData is missing"
        return response
    }
    if (!(request.data instanceof Map)) {
        response.data = "The required 'data'  in the formData is missing"
        return response
    }

    def object = request.data
    if (!object.containsKey("condition")) {
        response.condition = "The required 'condition'  in the 'data' of formData is missing"
        return response
    }

    def maliciousCode = "Malicious code 'System' class detected"

    if (object.condition?.contains("System")) {
        response.condition = maliciousCode + " on condition"
        return response
    }

    if (object.containsKey("filter") && object.filter?.contains("System")) {
        response.filter = maliciousCode + " on filter"
        return response
    }

    return response
}
